    std::string out;
    out.resize(raw.size() * 2);
    for (size_t i = 0; i < raw.size(); ++i) {
        unsigned char c = (unsigned char)raw[i];
        out[2 * i] = d[c >> 4]; out[2 * i + 1] = d[c & 15];
    }
    return out;
}
inline std::string unhex(const std::string& hex) {
    if (hex.size() % 2) throw std::runtime_error("hex length");
    std::string raw(hex.size() / 2, '\\0');
    for (size_t i = 0; i < raw.size(); ++i) {
        int hi, lo;
        char a = hex[2 * i], b = hex[2 * i + 1];
        hi = (a >= '0' && a <= '9') ? a - '0' : (a >= 'a' && a <= 'f') ? a - 'a' + 10 : (a >= 'A' && a <= 'F') ? a - 'A' + 10 : -1;
        lo = (b >= '0' && b <= '9') ? b - '0' : (b >= 'a' && b <= 'f') ? b - 'a' + 10 : (b >= 'A' && b <= 'F') ? b - 'A' + 10 : -1;
        if (hi < 0 || lo < 0) throw std::runtime_error("hex digit");
        raw[i] = (char)((hi << 4) | lo);
    }
    return raw;
}

