"""Immutable FIB versions, canonical forwarding runs and forwarding changes.

All addresses are full unsigned 128-bit integers; U = 2**128 is the exclusive
upper domain bound and is never a run start.
"""
import heapq
from bisect import bisect_right

U = 1 << 128
MAX_RUNS = 64
MAX_TOTAL_RUNS = 128


def bound_hex(value):
    if value == U:
        return "1" + "0" * 32
    return "%032x" % value


def runs_of(routes):
    """routes: {(start, length): hop} -> (starts list, hops list with None)."""
    adds, rems = {}, {}
    for (start, length), hop in routes.items():
        adds.setdefault(start, []).append((length, hop))
        end = start + (1 << (128 - length))
        if end < U:
            rems.setdefault(end, []).append((length, hop))
    positions = sorted(set(adds) | set(rems) | {0})
    live = {}
    heap = []
    starts, hops = [], []
    for pos in positions:
        for length, _hop in rems.get(pos, ()):
            live.pop(length, None)
        for length, hop in adds.get(pos, ()):
            live[length] = hop
            heapq.heappush(heap, -length)
        while heap and -heap[0] not in live:
            heapq.heappop(heap)
        value = live[-heap[0]] if heap else None
        if not hops or hops[-1] != value:
            starts.append(pos)
            hops.append(value)
    return starts, hops


def publish(initial, transactions):
    """Every committed immutable version, initial (version 0) first."""
    versions = []
    routes = {}
    for route, hop in initial:
        routes[route] = hop          # last initial row wins
    versions.append(runs_of(routes))
    for changes in transactions:
        for change in changes:
            op, route, hop = change
            if op == "set":
                routes[route] = hop
            else:
                routes.pop(route, None)
        versions.append(runs_of(routes))
    return versions


def value_at(starts, hops, address):
    return hops[bisect_right(starts, address) - 1]


def run_index(starts, address):
    return bisect_right(starts, address) - 1


def diff(one, two):
    """Forwarding changes between two committed versions."""
    s1, h1 = one
    s2, h2 = two
    bounds = sorted(set(s1) | set(s2))
    rows = []
    for i, x in enumerate(bounds):
        nxt = bounds[i + 1] if i + 1 < len(bounds) else U
        old = value_at(s1, h1, x)
        new = value_at(s2, h2, x)
        if old != new:
            rows.append([x, nxt, old, new])
    merged = []
    for row in rows:
        if merged and merged[-1][1] == row[0] and merged[-1][2] == row[2] and merged[-1][3] == row[3]:
            merged[-1][1] = row[1]
        else:
            merged.append(row)
    return [[bound_hex(a), bound_hex(b), o, n] for a, b, o, n in merged]


def interval_weights(starts, bursts):
    """Exact Q[i][j] and T[i][j] tables for one version."""
    size = len(starts)
    q = [[0] * (size + 1) for _ in range(size + 1)]
    t = [[0] * (size + 1) for _ in range(size + 1)]
    for version, repeat, addresses in bursts:
        idx = sorted(run_index(starts, address) for address in addresses)
        counts = [0] * (size + 1)
        for rank in idx:
            for i in range(rank + 1, size + 1):
                counts[i] += 1
        for i in range(size):
            for j in range(i + 1, size + 1):
                if counts[j] != counts[i]:
                    q[i][j] += repeat * (counts[j] - counts[i])
                    t[i][j] += repeat
                else:
                    q[i][j] += repeat * (counts[j] - counts[i])
    return q, t
