"""Cache-budgeted IPv6 image compiler, protocol 3.

Reads one JSON request through stdin to EOF and writes exactly one JSON
result (or {"error":"invalid"}) to stdout.  Forwarding compilation is also the
domain check: every committed version must have at most 64 canonical runs and
at most 128 runs summed over the whole request.
"""
import json
import sys
import native  # Build/transport helpers for the supplied scalar library.
import fib
import layout
import planner
from protocol import Invalid, MAX_INPUT, parse_request

sys.setrecursionlimit(10000)


def burst_work(image, costs, burst_answers):
    """Exact published work model, recomputed from the submitted bytes."""
    hit, miss, dec = costs
    _size, nodes, _order, _hops = layout.decode(image)
    total = 0
    for repeat, answers in burst_answers:
        visits, touched = {}, []
        for answer in answers:
            for off in answer[2]:
                if off not in visits:
                    visits[off] = 0
                    touched.append(off)
                visits[off] += 1
        for off in touched:
            node = nodes[off]
            keys = len(node["keys"])
            lanes = layout.LANES[node["mode"]]
            total += repeat * (node["pages"] * (hit if node["cached"] else miss)
                               + ((keys + lanes - 1) // lanes + dec[node["mode"]]) * visits[off])
    return total


def validate(starts, hops, nodes, image):
    """Legal-tree and image agreement check for one version."""
    if len(starts) < 1 or len(starts) > fib.MAX_RUNS:
        return False
    if len(starts) != len(hops):
        return False
    for lo, hi in zip(starts, starts[1:]):
        if not lo < hi:
            return False
    if starts[0] != 0:
        return False
    if not nodes or len(nodes) > 2 * len(starts) - 1:
        return False
    if nodes[0]["lo"] != 0 or nodes[0]["span"] != len(starts):
        return False
    ends = [n["lo"] + n["span"] for n in nodes]
    seen = []
    queue = [0]
    while queue:
        index = queue.pop(0)
        seen.append(index)
        node = nodes[index]
        if not layout.legal(node, starts):
            return False
        children = node["children"]
        if children:
            if len(children) > len(node["span"] if False else [0] * len(children)):
                return False
            cursor = node["lo"]
            for child in children:
                if child <= index or child >= len(nodes) or child in seen:
                    return False
                if nodes[child]["lo"] != cursor:
                    return False
                if ends[child] > ends[index]:
                    return False
                cursor = ends[child]
            if cursor != ends[index]:
                return False
        else:
            if node["span"] > 8:
                return False
        queue.extend(children)
    if len(seen) != len(nodes) or seen != list(range(len(nodes))):
        return False
    resident = sum(layout.node_pages(n) for n in nodes if n["cached"])
    return resident, image == layout.build(starts, hops, nodes).hex()


def compile_case(case, versions):
    """Globally optimal images, forwarding changes and lookup paths."""
    costs = case["costs"]
    budget = case["cache_pages"]
    bursts = case["bursts"]
    per_version = [[] for _ in versions]
    for index, (version, repeat, addresses) in enumerate(bursts):
        starts = versions[version][0]
        per_version[version].append((repeat, [fib.run_index(starts, a) for a in addresses]))
    layouts = None
    if native.try_build():
        try:
            layouts = native.plan(versions, per_version, costs, budget)
        except Exception:
            layouts = None
    if layouts is None:
        weights = []
        for starts, hops in versions:
            q, t = fib.interval_weights(starts, [(v, r, a) for (v, r, a) in bursts if v is None])
            weights.append(None)
        weights = []
        for version_index, (starts, hops) in enumerate(versions):
            sub = [(v, r, a) for (v, r, a) in bursts if v == version_index]
            q, t = fib.interval_weights(starts, sub)
            weights.append((q, t))
        layouts = planner.plan_case(versions, weights, costs, budget)
    if len(layouts) != len(versions):
        raise RuntimeError("plan shape")
    resident = 0
    for nodes in layouts:
        resident += sum(layout.node_pages(n) for n in nodes if n["cached"])
    if resident > budget:
        raise RuntimeError("plan budget")

    results, answers_by_version = [], {}
    for version_index, (starts, hops) in enumerate(versions):
        nodes = layouts[version_index]
        image = layout.build(starts, hops, nodes)
        ok = validate(starts, hops, nodes, image.hex())
        if ok is False:
            raise RuntimeError("layout rejected")
        addresses, owners = [], []
        for index, (version, repeat, group) in enumerate(bursts):
            if version == version_index:
                owners.append((index, repeat, len(addresses)))
                addresses.extend(group)
        packed = None
        if native.available():
            try:
                hex_text, found = native.pack(starts, hops, nodes, addresses)
                if hex_text == image.hex() and len(found) == len(addresses):
                    packed = found
            except Exception:
                packed = None
        if packed is None:
            _size, parsed, _order, decoded = layout.decode(image)
            packed = [list(layout.search(parsed, decoded, address)) for address in addresses]
        answers_by_version[version_index] = (packed, owners)

    versions_out, pages = [], 0
    for version_index, (starts, hops) in enumerate(versions):
        image = layout.build(starts, hops, layouts[version_index])
        pages += len(image) // 64
        versions_out.append({"starts": ["%032x" % s for s in starts],
                             "hops": list(hops),
                             "image": image.hex()})
    bursts_out = [[None] * len(group) for (_v, _r, group) in bursts]
    work = 0
    for version_index, (starts, hops) in enumerate(versions):
        packed, owners = answers_by_version[version_index]
        image = layout.build(starts, hops, layouts[version_index])
        burst_answers = []
        for index, repeat, first in owners:
            count = len(bursts[index][2])
            group = packed[first:first + count]
            bursts_out[index] = group
            burst_answers.append((repeat, group))
        work += burst_work(image, costs, burst_answers)
    return {"versions": versions_out,
            "changes": [fib.diff(versions[i], versions[i + 1]) for i in range(len(versions) - 1)],
            "bursts": bursts_out,
            "objective": [work, pages]}


def compile_request(cases):
    # Domain validation also requires compiling forwarding runs: <=64 per
    # version and <=128 summed across all versions/cases of the request.
    # Addresses and route networks are full unsigned 128-bit integers.
    compiled, total_runs = [], 0
    for case in cases:
        versions = fib.publish(case["initial"], case["transactions"])
        for starts, hops in versions:
            if len(starts) > fib.MAX_RUNS or len(starts) != len(hops):
                raise Invalid("forwarding run bound")
            total_runs += len(starts)
        if total_runs > fib.MAX_TOTAL_RUNS:
            raise Invalid("forwarding run bound")
        compiled.append((case, versions))
    if total_runs > fib.MAX_TOTAL_RUNS:
        raise Invalid("forwarding run bound")
    return {"cases": [compile_case(case, versions) for case, versions in compiled]}


def main():
    try:
        cases = parse_request(sys.stdin.buffer.read(MAX_INPUT + 1))
        result = compile_request(cases)
    except Invalid:
        result = {"error": "invalid"}
    json.dump(result, sys.stdout, separators=(",", ":"), allow_nan=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
