"""Cache-budgeted IPv6 image compiler, protocol 3.

Reads one JSON request through stdin to EOF and writes exactly one JSON
result (or {"error":"invalid"}) to stdout.  Forwarding compilation doubles as
the domain check: every committed version must have at most 64 canonical runs
and at most 128 runs summed over every committed version of the request.
"""
import json
import sys
import native  # Build/transport helpers for the supplied scalar library.
import fib
import layout
import planner
from protocol import Invalid, MAX_INPUT, parse_request

sys.setrecursionlimit(10000)


def burst_work(image, costs, burst_answers):
    """Exact published work model, recomputed from the submitted bytes."""
    hit, miss, dec = costs
    _size, nodes, _order, _hops = layout.decode(image)
    total = 0
    for repeat, answers in burst_answers:
        visits, touched = {}, []
        for answer in answers:
            for off in answer[2]:
                if off not in visits:
                    visits[off] = 0
                    touched.append(off)
                visits[off] += 1
        for off in touched:
            node = nodes[off]
            keys = len(node["keys"])
            lanes = layout.LANES[node["mode"]]
            total += repeat * (node["pages"] * (hit if node["cached"] else miss)
                               + ((keys + lanes - 1) // lanes + dec[node["mode"]]) * visits[off])
    return total


def check_layout(starts, hops, nodes):
    """Legal-tree agreement with the canonical runs of one version."""
    size = len(starts)
    if size < 1 or size > fib.MAX_RUNS or not nodes or len(nodes) > 2 * size - 1:
        return False
    if nodes[0]["lo"] != 0 or nodes[0]["span"] != size:
        return False
    ends = [n["lo"] + n["span"] for n in nodes]
    order, queue = [], [0]
    while queue:
        index = queue.pop(0)
        order.append(index)
        node = nodes[index]
        if not layout.legal(node, starts):
            return False
        children = node["children"]
        if children:
            if len(children) < 2 or len(children) > 9 or len(children) > node["span"]:
                return False
            cursor = node["lo"]
            for child in children:
                if not index < child < len(nodes) or child in order:
                    return False
                if nodes[child]["lo"] != cursor or ends[child] > ends[index]:
                    return False
                cursor = ends[child]
            if cursor != ends[index]:
                return False
        elif node["span"] > 8:
            return False
        queue.extend(children)
    if order != list(range(len(nodes))):
        return False
    return True


def plan_layouts(versions, bursts, costs, budget, native_ready):
    """Jointly optimal layout of every immutable version of one case."""
    per_version = [[] for _ in versions]
    for version, repeat, addresses in bursts:
        starts = versions[version][0]
        per_version[version].append((repeat, [fib.run_index(starts, a) for a in addresses]))
    if native_ready:
        try:
            layouts = native.plan(versions, per_version, costs, budget)
            if len(layouts) == len(versions) and all(
                    check_layout(starts, hops, nodes)
                    for (starts, hops), nodes in zip(versions, layouts)):
                return layouts
        except Exception:
            layouts = None
    weights = []
    for index, (starts, _hops) in enumerate(versions):
        members = [(version, repeat, addresses)
                   for version, repeat, addresses in bursts if version == index]
        q, t = fib.interval_weights(starts, members)
        weights.append((q, t))
    return planner.plan_case(versions, weights, costs, budget)


def compile_case(case, versions, native_ready):
    """Optimal images, forwarding changes and lookup paths for one case."""
    costs, budget, bursts = case["costs"], case["cache_pages"], case["bursts"]
    layouts = plan_layouts(versions, bursts, costs, budget, native_ready)
    if len(layouts) != len(versions):
        raise RuntimeError("plan shape")
    burst_out = [[] for _ in bursts]
    work = pages = resident = 0
    versions_out = []
    for index, (starts, hops) in enumerate(versions):
        nodes = layouts[index]
        if not check_layout(starts, hops, nodes):
            raise RuntimeError("layout rejected")
        image = layout.build(starts, hops, nodes)
        resident += sum(layout.node_pages(n) for n in nodes if n["cached"])
        addresses, spans = [], []
        for bindex, (version, _repeat, group) in enumerate(bursts):
            if version == index:
                spans.append((bindex, len(addresses), len(addresses) + len(group)))
                addresses.extend(group)
        packed = None
        if native_ready:
            try:
                hex_text, found = native.pack(starts, hops, nodes, addresses)
                if hex_text == image.hex() and len(found) == len(addresses):
                    packed = found
            except Exception:
                packed = None
        if packed is None:
            _size, parsed, _order, decoded = layout.decode(image)
            packed = [layout.search(parsed, decoded, address) for address in addresses]
        for bindex, first, last in spans:
            burst_out[bindex] = [list(entry) for entry in packed[first:last]]
        pages += len(image) // 64
        versions_out.append({"starts": ["%032x" % s for s in starts],
                             "hops": list(hops),
                             "image": image.hex()})
        burst_answers = [(bursts[b][1], burst_out[b])
                         for b in range(len(bursts)) if bursts[b][0] == index]
        work += burst_work(image, costs, burst_answers)
    if resident > budget:
        raise RuntimeError("resident page budget")
    return {"versions": versions_out,
            "changes": [fib.diff(versions[i], versions[i + 1])
                        for i in range(len(versions) - 1)],
            "bursts": burst_out,
            "objective": [work, pages]}


def compile_request(cases, native_ready=False):
    # Domain validation also requires compiling forwarding runs: <=64 per
    # version and <=128 summed across all versions/cases of the request.
    # Addresses and route networks are full unsigned 128-bit integers.
    compiled, total_runs = [], 0
    for case in cases:
        versions = fib.publish(case["initial"], case["transactions"])
        for starts, hops in versions:
            if len(starts) > fib.MAX_RUNS:
                raise Invalid("forwarding run bound")
            total_runs += len(starts)
        if total_runs > fib.MAX_TOTAL_RUNS:
            raise Invalid("forwarding run bound")
        compiled.append((case, versions))
    if total_runs > fib.MAX_TOTAL_RUNS:
        raise Invalid("forwarding run bound")
    return {"cases": [compile_case(case, versions, native_ready) for case, versions in compiled]}


def main():
    data = sys.stdin.buffer.read(MAX_INPUT + 1)
    try:
        cases = parse_request(data)
    except Invalid:
        json.dump({"error": "invalid"}, sys.stdout, separators=(",", ":"), allow_nan=False)
        sys.stdout.write("\n")
        return
    try:
        result = compile_request(cases, native.try_build())
    except Exception:
        # never emit a partial answer: retry the whole batch without the native
        # subsystem, and only then report the protocol's single error value
        try:
            result = compile_request(cases, False)
        except Exception:
            result = {"error": "invalid"}
    json.dump(result, sys.stdout, separators=(",", ":"), allow_nan=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()

