def bound_hex(value):
    if value == U:
        return "1" + "0" * 32
    return "%032x" % value


def runs_of(routes):
    """routes: {(start, length): hop} -> (starts list, hops list with None)."""
    adds, rems = {}, {}
    for (start, length), hop in routes.items():
